export type OrderStatus = "pending" | "paid" | "shipped";

export interface Order {
  id: string;
  status: OrderStatus;
  totalCents: number;
}

export interface ShippedOrder extends Order {
  status: "shipped";
  trackingNumber: string;
}

export function describe(order: Order): string {
  const total = (order.totalCents / 100).toFixed(2);
  return `${order.id} is ${order.status} ($${total})`;
}

export function trackingLabel(order: ShippedOrder): string {
  return `${order.id} ships with ${order.trackingNumber}`;
}

const orders: Order[] = [
  { id: "B-7", status: "pending", totalCents: 1800 },
  { id: "B-8", status: "paid", totalCents: 4250 },
];
const parcel: ShippedOrder = { id: "B-9", status: "shipped", totalCents: 990, trackingNumber: "1Z999AA1" };

for (const order of orders) {
  console.log(describe(order));
}
console.log(trackingLabel(parcel));
